package dev.groupplanning.android.authprobe;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.*;
import android.view.accessibility.*;
import java.io.*;
import java.nio.file.Files;
import java.util.*;
public final class AuthProbe extends Instrumentation {
 private String sdkValue="profile-fields-full"; private Bundle args, result=new Bundle(); private org.json.JSONArray actions=new org.json.JSONArray(); private Activity activity; private Object gate,probe; private Class<?> gateClass,probeClass; private File output; private ActivityMonitor monitor; private String oldServices,oldEnabled;
 private UiAutomation automation(){return getUiAutomation(args!=null&&args.getString("talkback","false").equals("true")?UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES:0);}
 @Override public void onCreate(Bundle value){args=value;start();}
 private AccessibilityNodeInfo find(AccessibilityNodeInfo node,String key){
  if(node==null)return null;String text=String.valueOf(node.getText()),desc=String.valueOf(node.getContentDescription());
  if(text.equals(key)||desc.equals(key))return node;for(int i=0;i<node.getChildCount();i++){AccessibilityNodeInfo child=find(node.getChild(i),key);if(child!=null)return child;}return null;
 }
 private boolean effectivelyEnabled(AccessibilityNodeInfo n){while(n!=null){if(!n.isEnabled())return false;if(n.isClickable())return true;n=n.getParent();}return false;}
 private boolean click(AccessibilityNodeInfo n){while(n!=null&&!n.isClickable())n=n.getParent();return n!=null&&n.performAction(AccessibilityNodeInfo.ACTION_CLICK);}
 private AccessibilityNodeInfo node(String key){automation().clearCache();return find(automation().getRootInActiveWindow(),key);}
 private AccessibilityNodeInfo await(String key,long timeout){long end=SystemClock.uptimeMillis()+timeout;while(SystemClock.uptimeMillis()<end){AccessibilityNodeInfo n=node(key);if(n!=null)return n;SystemClock.sleep(80);}throw new IllegalStateException("Missing actual node "+key);}
 private String requests()throws Exception{return String.valueOf(probeClass.getMethod("getRequests").invoke(probe));}
 private void delay(long value)throws Exception{gateClass.getMethod("setArtificialRoundTripMillis",long.class).invoke(gate,value);}
 private void capture(String name)throws Exception{waitForIdleSync();SystemClock.sleep(500);record("capture "+name);org.json.JSONObject meta=new org.json.JSONObject().put("at",java.time.Instant.now().toString()).put("activityClass",activity.getClass().getName()).put("locale",activity.getResources().getConfiguration().getLocales().toLanguageTags()).put("fontScale",activity.getResources().getConfiguration().fontScale).put("widthDp",activity.getResources().getConfiguration().screenWidthDp).put("heightDp",activity.getResources().getConfiguration().screenHeightDp).put("densityDpi",activity.getResources().getDisplayMetrics().densityDpi);try(PrintWriter m=new PrintWriter(new File(output,name+".capture.json"))){m.print(meta.toString(2));}Bitmap bitmap=automation().takeScreenshot();try(FileOutputStream stream=new FileOutputStream(new File(output,name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,stream);}bitmap.recycle();try(PrintWriter out=new PrintWriter(new File(output,name+"-nodes.txt"))){automation().clearCache();walk(automation().getRootInActiveWindow(),out);}}
 private void walk(AccessibilityNodeInfo n,PrintWriter out){if(n==null)return;Rect b=new Rect();n.getBoundsInScreen(b);out.println("text="+n.getText()+" desc="+n.getContentDescription()+" state="+n.getStateDescription()+" enabled="+n.isEnabled()+" a11yFocused="+n.isAccessibilityFocused()+" selected="+n.isSelected()+" bounds="+b+" actions="+n.getActionList());for(int i=0;i<n.getChildCount();i++)walk(n.getChild(i),out);}
 private ActivityMonitor sdk(boolean cancel)throws Exception{Intent intent=new Intent();if(!cancel){Class<?> token=getTargetContext().getClassLoader().loadClass("com.yandex.authsdk.YandexAuthToken");Object value=null;for(java.lang.reflect.Constructor<?> c:token.getConstructors()){Class<?>[] types=c.getParameterTypes();if(types.length==2&&types[0]==String.class){value=c.newInstance(sdkValue,types[1]==long.class?Long.valueOf(3600):Integer.valueOf(3600));break;}}if(value==null)throw new IllegalStateException("SDK token constructor missing");intent.putExtra("com.yandex.authsdk.EXTRA_TOKEN",(Parcelable)value);}return addMonitor("com.yandex.authsdk.internal.AuthSdkActivity",new ActivityResult(cancel?Activity.RESULT_CANCELED:Activity.RESULT_OK,intent),true);}
 private void record(String action)throws Exception{actions.put(new org.json.JSONObject().put("at",java.time.Instant.now().toString()).put("action",action));try(PrintWriter w=new PrintWriter(new File(output,"interaction.json"))){w.print(actions.toString(2));}}
 private String shell(String c)throws Exception{try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(automation().executeShellCommand(c))){ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)o.write(b,0,n);return o.toString("UTF-8").trim();}}
 private void assertPage(int i)throws Exception{AccessibilityNodeInfo r=await("Страница знакомства",1000);AccessibilityNodeInfo.RangeInfo info=r.getRangeInfo();if(info==null||Math.abs(info.getCurrent()-i)>.01)throw new IllegalStateException("Expected actual range "+i+" but "+(info==null?"null":info.getCurrent()));record("Assert actual range "+i+" of0..7");}
 private void page(int i)throws Exception{AccessibilityNodeInfo range=await("Страница знакомства",1500);Bundle b=new Bundle();b.putFloat(AccessibilityNodeInfo.ACTION_ARGUMENT_PROGRESS_VALUE,i);if(!range.performAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),b))throw new IllegalStateException("range action rejected "+i);SystemClock.sleep(450);assertPage(i);AccessibilityNodeInfo f=await("Страница знакомства",1000);boolean focused=f.performAction(AccessibilityNodeInfo.ACTION_ACCESSIBILITY_FOCUS);record("SetProgress page "+(i+1)+" a11yFocusAccepted="+focused+" range="+f.getRangeInfo()+" state="+f.getStateDescription());}
 private AccessibilityNodeInfo scroll(AccessibilityNodeInfo n){if(n==null)return null;if(n.isScrollable()&&n.getClassName()!=null&&n.getClassName().toString().equals("android.widget.ScrollView"))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo c=scroll(n.getChild(i));if(c!=null)return c;}return null;}
 private void touch(float x1,float y1,float x2,float y2)throws Exception{long t=SystemClock.uptimeMillis();automation().injectInputEvent(android.view.MotionEvent.obtain(t,t,0,x1,y1,0),true);for(int j=1;j<=12;j++){SystemClock.sleep(12);automation().injectInputEvent(android.view.MotionEvent.obtain(t,SystemClock.uptimeMillis(),2,x1+(x2-x1)*j/12,y1+(y2-y1)*j/12,0),true);}automation().injectInputEvent(android.view.MotionEvent.obtain(t,SystemClock.uptimeMillis(),1,x2,y2,0),true);SystemClock.sleep(400);record("Real touch "+x1+","+y1+" to "+x2+","+y2);}
 private void navigation()throws Exception{if(args.getString("talkback","false").equals("true")){oldServices=shell("settings get secure enabled_accessibility_services");oldEnabled=shell("settings get secure accessibility_enabled");if(!oldServices.equals("null")&&!oldServices.isEmpty())throw new IllegalStateException("Existing accessibility service must be preserved");shell("settings put secure enabled_accessibility_services com.google.android.marvin.talkback/com.google.android.marvin.talkback.TalkBackService");shell("settings put secure accessibility_enabled 1");SystemClock.sleep(1600);android.view.accessibility.AccessibilityManager manager=getTargetContext().getSystemService(android.view.accessibility.AccessibilityManager.class);record("Actual TalkBack enabled="+manager.isEnabled()+" touchExploration="+manager.isTouchExplorationEnabled());if(!manager.isEnabled()||!manager.isTouchExplorationEnabled())throw new IllegalStateException("TalkBack not bound");AccessibilityNodeInfo active=automation().getRootInActiveWindow();if(active!=null&&String.valueOf(active.getPackageName()).contains("permissioncontroller")){for(String deny:new String[]{"Don’t allow","Don\'t allow","Не разрешать"}){AccessibilityNodeInfo d=find(active,deny);if(d!=null){click(d);break;}}}runOnMainSync(()->activity.startActivity(new Intent(activity,activity.getClass()).addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT)));SystemClock.sleep(600);}probeClass.getMethod("reset").invoke(probe);capture("slide-1");if(!args.getString("talkback","false").equals("true")){click(await("Далее",1500));SystemClock.sleep(400);assertPage(1);capture("next-to-2");float w=getTargetContext().getResources().getDisplayMetrics().widthPixels;touch(w*.2f,400,w*.8f,400);assertPage(0);capture("swipe-back-to-1");page(0);}for(int i=0;i<8;i++){page(i);if(!args.getString("talkback","false").equals("true")){float w=getTargetContext().getResources().getDisplayMetrics().widthPixels;touch(w/2,400,w/2,400);}capture("slide-"+(i+1));if(i==1){AccessibilityNodeInfo calendar=node("Календарь");if(calendar==null||!click(calendar))throw new IllegalStateException("Calendar local toggle missing");SystemClock.sleep(300);capture("calendar-local");record("Local calendar toggle; requests="+requests());click(await("Список",1000));}AccessibilityNodeInfo sc=scroll(automation().getRootInActiveWindow());int scrolls=0;while(sc!=null&&scrolls<8&&sc.performAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD)){SystemClock.sleep(180);scrolls++;automation().clearCache();sc=scroll(automation().getRootInActiveWindow());}record("Full body scroll page "+(i+1)+" forward steps="+scrolls);if(scrolls>0)capture("slide-"+(i+1)+"-scrolled");}record("requests after inert page illustrations="+requests());automation().executeShellCommand("input keyevent KEYCODE_BACK").close();SystemClock.sleep(400);assertPage(6);capture("system-back-to-7");click(await("Пропустить",1500));SystemClock.sleep(400);assertPage(7);capture("skip-to-8");click(await("Войти через Яндекс ID",1500));await("Не удалось открыть вход",5000);capture("error");click(await("Войти через Яндекс ID",1500));await("Не удалось открыть вход",5000);capture("retry");runOnMainSync(()->activity.recreate());SystemClock.sleep(900);assertPage(7);capture("recreation-return");runOnMainSync(()->activity.setRequestedOrientation(0));SystemClock.sleep(900);capture("landscape");runOnMainSync(()->activity.setRequestedOrientation(1));SystemClock.sleep(900);assertPage(7);capture("landscape-return");result.putString("requests",requests());}
 @Override public void callActivityOnResume(Activity a){super.callActivityOnResume(a);if(a.getPackageName().equals(getTargetContext().getPackageName()))activity=a;}
 @Override public void onStart(){try{
  Context context=getTargetContext();output=new File(context.getFilesDir(),"entry-final-r9-"+args.getString("label","standard"));output.mkdirs();
  try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(automation().executeShellCommand("cat "+args.getString("fixturePath")))){Files.copy(in,new File(context.getNoBackupFilesDir(),"ui-fixture.json").toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}
  ClassLoader loader=context.getClassLoader();gateClass=loader.loadClass("dev.groupplanning.android.QaResponseGate");gate=gateClass.getField("INSTANCE").get(null);probeClass=loader.loadClass("dev.groupplanning.android.QaChatProbe");probe=probeClass.getField("INSTANCE").get(null);
  Intent launchIntent=new Intent().setClassName(context.getPackageName(),"dev.groupplanning.android.MainActivity").putExtra("scenario",args.getString("mode","auth").equals("launch")?"calendar":args.getString("mode","auth").equals("navigation")?"onboarding":"profile-fields").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);if(args.getString("mode","auth").equals("invitation"))launchIntent.setData(android.net.Uri.parse("group-planning-android-qa://i/QUFBQUFBQUFBQUFBQUFBQQ"));activity=startActivitySync(launchIntent);waitForIdleSync();
  if(args.getString("mode","auth").equals("launch")){oldServices=shell("settings get secure enabled_accessibility_services");oldEnabled=shell("settings get secure accessibility_enabled");if(!oldServices.equals("null")&&!oldServices.isEmpty())throw new IllegalStateException("Existing accessibility service must be preserved");shell("settings put secure enabled_accessibility_services com.google.android.marvin.talkback/com.google.android.marvin.talkback.TalkBackService");shell("settings put secure accessibility_enabled 1");SystemClock.sleep(1500);android.view.accessibility.AccessibilityManager manager=context.getSystemService(android.view.accessibility.AccessibilityManager.class);record("Actual TalkBack enabled="+manager.isEnabled()+" touchExploration="+manager.isTouchExplorationEnabled());if(!manager.isEnabled()||!manager.isTouchExplorationEnabled())throw new IllegalStateException("TalkBack not bound");runOnMainSync(()->activity.startActivity(new Intent(activity,activity.getClass()).addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT)));AccessibilityNodeInfo launch=await("somewhere, приложение загружается",3000);boolean focused=launch.performAction(AccessibilityNodeInfo.ACTION_ACCESSIBILITY_FOCUS);record("Launch accessible focus accepted="+focused);capture("talkback-launch-reduced");result.putBoolean("actualTalkBack",true);return;}
  if(args.getString("mode","auth").equals("invitation")){await("Войти через Яндекс ID",10000);capture("invitation-guest-bypass");monitor=sdk(false);click(await("Войти через Яндекс ID",1500));await("Приду",12000);SystemClock.sleep(600);await("Приду",3000);if(node("Приглашение недоступно")!=null)throw new IllegalStateException("Invitation settled error");capture("invitation-return");result.putString("requestsAfterInvitationLogin",requests());result.putInt("sdkHits",monitor.getHits());return;}await("Пропустить",8000); if(args.getString("mode","auth").equals("navigation")){navigation();return;} AccessibilityNodeInfo firstRange=await("Страница знакомства",1000);Bundle seventh=new Bundle();seventh.putFloat(AccessibilityNodeInfo.ACTION_ARGUMENT_PROGRESS_VALUE,6);firstRange.performAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),seventh);SystemClock.sleep(400);probeClass.getMethod("reset").invoke(probe);AccessibilityNodeInfo fastNext=await("Далее",2000);long rapidStart=SystemClock.uptimeMillis();click(fastNext);click(fastNext);result.putLong("rapidNextCallsMillis",SystemClock.uptimeMillis()-rapidStart);SystemClock.sleep(400);result.putString("requestsAfterRapidNext",requests());result.putBoolean("rapidNextRetainsLastPage",node("Откройте\nсвои встречи.")!=null);capture("rapid-next-no-autoauth");AccessibilityNodeInfo login=await("Войти через Яндекс ID",5000);Rect before=new Rect();login.getBoundsInScreen(before);capture("ready");
  probeClass.getMethod("reset").invoke(probe);monitor=sdk(true);delay(10000);click(login);result.putLong("clickedAtUptime",SystemClock.uptimeMillis());SystemClock.sleep(400);capture("busy-early");result.putLong("earlyCapturedAtUptime",SystemClock.uptimeMillis());login=await("Войти через Яндекс ID",3000);Rect busy=new Rect();login.getBoundsInScreen(busy);
  result.putBoolean("busyLabelNodeEnabled",login.isEnabled());AccessibilityNodeInfo owner=login;while(owner!=null&&!owner.isClickable()&&owner.isEnabled())owner=owner.getParent();result.putBoolean("busyEffectiveControlEnabled",owner!=null&&owner.isEnabled());result.putString("busyState",String.valueOf(login.getStateDescription()));result.putBoolean("busyButtonBoundsStable",before.equals(busy));result.putString("requestsDuringBusy",requests());
  AccessibilityNodeInfo range=await("Страница знакомства",1000);Bundle progress=new Bundle();progress.putFloat(AccessibilityNodeInfo.ACTION_ARGUMENT_PROGRESS_VALUE,0);result.putBoolean("busySetProgressAccepted",range.performAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),progress));
  automation().executeShellCommand("input keyevent KEYCODE_BACK").close();SystemClock.sleep(200);result.putBoolean("busyBackRetainsLastPage",node("Откройте\nсвои встречи.")!=null);result.putBoolean("secondBusyClickAccepted",click(login));capture("busy");
  long end=SystemClock.uptimeMillis()+16000;while(SystemClock.uptimeMillis()<end){login=node("Войти через Яндекс ID");if(login!=null&&effectivelyEnabled(login)&&monitor.getHits()>0&&node("Страница знакомства").isEnabled())break;SystemClock.sleep(100);}result.putInt("cancelSdkMonitorHits",monitor.getHits());result.putString("requestsAfterCancel",requests());if(!effectivelyEnabled(await("Войти через Яндекс ID",1000)))throw new IllegalStateException("Cancel not ready after timeout");SystemClock.sleep(350);record("Cancel settled effectiveCTA/rangeenabled; compositor350ms");capture("cancel-return");removeMonitor(monitor);monitor=null;delay(0);
  result.putBoolean("cancelRetainsLastPage",node("Откройте\nсвои встречи.")!=null);result.putBoolean("cancelNoInlineFailure",node("Не удалось открыть вход")==null&&node("Не удалось войти")==null);
  sdkValue="profile-fields-invalid";monitor=sdk(false);click(await("Войти через Яндекс ID",2000));await("Не удалось открыть вход",12000);result.putString("requestsAfterHttpError",requests());capture("http-error");removeMonitor(monitor);monitor=null;sdkValue="profile-fields-full";
  monitor=sdk(false);click(await("Войти через Яндекс ID",2000));long successEnd=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<successEnd){if(node("Профиль")!=null)break;SystemClock.sleep(100);}result.putInt("successSdkMonitorHits",monitor.getHits());result.putBoolean("successHomeProfileVisible",node("Профиль")!=null);result.putString("requestsAfterSuccess",requests());capture("success-home");click(await("Профиль",2000));await("Вход через Яндекс ID",5000);capture("services-in-profile");
  result.putString("actualActivityLocale",activity.getResources().getConfiguration().getLocales().toLanguageTags());result.putString("sourceBoundary","Synthetic SDK token/RESULT_CANCELED; real loopback HTTP start/exchange; existing QA delay only");
 }catch(Throwable error){result.putString("error",error.toString());try{capture("failure");}catch(Throwable ignored){}}finally{try{if(oldServices!=null){shell(oldServices.equals("null")?"settings delete secure enabled_accessibility_services":"settings put secure enabled_accessibility_services "+oldServices);shell(oldEnabled.equals("null")?"settings delete secure accessibility_enabled":"settings put secure accessibility_enabled "+oldEnabled);}if(gate!=null)delay(0);}catch(Throwable ignored){}if(monitor!=null)removeMonitor(monitor);if(activity!=null)runOnMainSync(()->activity.finish());finish(result.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}}
}
